def _codex_cli_readiness() -> tuple[bool, str, dict]:
    """Check that a compatible Codex CLI is available before starting a pane."""
    binary = shutil.which("codex")
    details = {"binary": binary or "", "minimum": _CODEX_MIN_CLI_VERSION, "version": ""}
    if not binary:
        return False, "the codex CLI is not installed", details
    try:
        result = subprocess.run(
            [binary, "--version"], capture_output=True, text=True, timeout=10
        )
        text = ((result.stdout or "") + " " + (result.stderr or "")).strip()
        match = re.search(r"(\d+\.\d+\.\d+)", text)
        version = match.group(1) if match else ""
        details["version"] = version
        if result.returncode != 0 or not version:
            return False, "the codex CLI version could not be determined", details
        current = tuple(int(part) for part in version.split("."))
        minimum = tuple(int(part) for part in _CODEX_MIN_CLI_VERSION.split("."))
        if current < minimum:
            return False, f"codex {version} is older than required {_CODEX_MIN_CLI_VERSION}", details
    except Exception as exc:
        return False, f"codex CLI check failed: {type(exc).__name__}", details
    return True, "ready", details


def _muse_skills_inventory() -> list[dict]:
    """Return Muse's own skill inventory in the small shape used by the UI."""
    configured = str(MUSE_BINARY)
    binary = configured if MUSE_BINARY.is_absolute() else (shutil.which(configured) or configured)
    muse_env = os.environ.copy()
    muse_env.update({
        "MUSE_NO_AUTO_UPDATE": "1",
        "XDG_CONFIG_HOME": str(MUSE_CONFIG_HOME),
        "XDG_DATA_HOME": str(MUSE_DATA_HOME),
    })
    result = subprocess.run(
        [binary, "skills", "list", "--json"],
        capture_output=True,
        text=True,
        timeout=10,
        env=muse_env,
    )
    if result.returncode != 0:
        return []
    payload = json.loads(result.stdout or "{}")
    rows = payload.get("skills") if isinstance(payload, dict) else []
    if not isinstance(rows, list):
        return []
    inventory = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        name = str(row.get("name") or row.get("display_name") or "").strip()
        if not name:
            continue
        inventory.append({
            "name": name,
            "description": str(
                row.get("description") or row.get("short_description") or ""
            ).strip(),
            "scope": str(row.get("scope") or "").strip(),
        })
    return inventory


def _agent_cli_readiness() -> tuple[bool, str, dict]:
    """Validate the selected CLI and its local credential before pane launch."""
    if AGENT_KIND != "muse":
        return _codex_cli_readiness()
    configured = str(MUSE_BINARY)
    binary = configured if MUSE_BINARY.is_absolute() else (shutil.which(configured) or "")
    details = {
        "agent": AGENT_KIND,
        "binary": binary,
        "version": "",
        "auth_configured": False,
        "config_home": str(MUSE_CONFIG_HOME),
        "data_home": str(MUSE_DATA_HOME),
        "mcp_servers": [],
        "mcp_bridge_ready": False,
        "advisor_token_ready": False,
        "advisor_mcp_ready": False,
        "google_mcp_ready": False,
        "google_services": [],
        "browser_mcp_ready": False,
        "browser_id": "default",
        "skills_total": 0,
        "skills_user": 0,
        "skills_builtin": 0,
        "memory_tools": ["read_memory", "add_memory", "edit_memory"],
    }
    if not binary or not Path(binary).is_file() or not os.access(binary, os.X_OK):
        return False, "the Muse CLI is not installed", details
    try:
        result = subprocess.run(
            [binary, "--version"], capture_output=True, text=True, timeout=10
        )
        output = ((result.stdout or "") + " " + (result.stderr or "")).strip()
        match = re.search(r"(\d+\.\d+\.\d+)", output)
        details["version"] = match.group(1) if match else ""
        if result.returncode != 0 or not details["version"]:
            return False, "the Muse CLI version could not be determined", details
    except Exception as exc:
        return False, f"Muse CLI check failed: {type(exc).__name__}", details
    auth_file = MUSE_CONFIG_HOME / "muse" / "auth.json"
    try:
        stat = auth_file.stat()
        details["auth_configured"] = stat.st_size > 2
        if stat.st_mode & 0o077:
            return False, "the Muse credential permissions are too broad", details
    except OSError:
        pass
    if not details["auth_configured"]:
        return False, "the Muse credential is not configured", details
    try:
        settings = json.loads((MUSE_CONFIG_HOME / "muse" / "settings.json").read_text())
        servers = settings.get("mcp_servers") if isinstance(settings, dict) else {}
        if isinstance(servers, dict):
            details["mcp_servers"] = sorted(str(name) for name in servers)
    except Exception:
        pass
    details["mcp_bridge_ready"] = bool(
        MUSE_MCP_PYTHON.is_file()
        and os.access(MUSE_MCP_PYTHON, os.X_OK)
        and MUSE_MCP_BRIDGE.is_file()
    )
    if os.environ.get("ADVISOR_TOKEN", "").strip():
        details["advisor_token_ready"] = True
    else:
        try:
            token_stat = MUSE_ADVISOR_TOKEN_FILE.stat()
            details["advisor_token_ready"] = bool(
                token_stat.st_uid == os.geteuid()
                and not token_stat.st_mode & 0o077
                and token_stat.st_size > 0
            )
        except OSError:
            pass
    details["advisor_mcp_ready"] = bool(
        "advisor" in details["mcp_servers"]
        and details["mcp_bridge_ready"]
        and details["advisor_token_ready"]
    )
    google_credentials = MESSAGES_DIR / "connections" / "admin"
    details["google_services"] = [
        service
        for service in ("drive", "gmail", "calendar")
        if (google_credentials / f"{service}.json").is_file()
    ]
    details["google_mcp_ready"] = bool(
        "google" in details["mcp_servers"]
        and MUSE_MCP_PYTHON.is_file()
        and MUSE_GOOGLE_MCP_SCRIPT.is_file()
    )
    details["browser_mcp_ready"] = bool(
        "playwright-browser" in details["mcp_servers"]
        and MUSE_MCP_PYTHON.is_file()
        and MUSE_BROWSER_MCP_PROXY.is_file()
        and PLAYWRIGHT_MCP_CLI.is_file()
    )
    try:
        skills = _muse_skills_inventory()
        details["skills_total"] = len(skills)
        details["skills_user"] = sum(skill.get("scope") == "user" for skill in skills)
        details["skills_builtin"] = sum(
            skill.get("scope") in {"built-in", "bundled"} for skill in skills
        )
    except Exception:
        logger.debug("Could not inventory Muse skills", exc_info=True)
    if not details["advisor_mcp_ready"]:
        return False, "the owner-bound Advisor MCP is not ready", details
    return True, "ready", details


def _muse_credential_display() -> dict:
    """Return a safe identity for the Muse credential, never its secret value."""
    auth_file = MUSE_CONFIG_HOME / "muse" / "auth.json"
    try:
        auth = json.loads(auth_file.read_text())
    except Exception:
        return {}
    providers = auth.get("providers") if isinstance(auth, dict) else None
    if not isinstance(providers, dict) or not providers:
        return {}
    provider, raw = next(
        ((str(name), value) for name, value in providers.items() if isinstance(value, dict)),
        ("", {}),
    )
    if not provider:
        return {}
    api_key = str(raw.get("api_key") or "")
    access_token = str(raw.get("access_token") or "")
    secret = api_key or access_token
    suffix = secret[-4:] if secret else ""
    provider_label = "Meta Model API" if provider.lower() == "meta" else provider.title()
    credential_kind = "API key" if api_key else "access token"
    api_url = str(raw.get("api_base_url") or "")
    try:
        api_host = urlsplit(api_url).hostname or ""
    except ValueError:
        api_host = ""
    return {
        "provider": provider,
        "providerLabel": provider_label,
        "accountEmail": str(raw.get("user_email") or ""),
        "accountName": str(raw.get("user_full_name") or ""),
        "mechanism": str(raw.get("mechanism") or ""),
        "obtainedVia": str(raw.get("obtained_via") or ""),
        "credentialLabel": (
            f"{provider.title()} {credential_kind} ····{suffix}"
            if suffix
            else f"{provider.title()} {credential_kind}"
        ),
        "keySuffix": suffix,
        "apiHost": api_host,
    }


def _ensure_muse_runtime_settings() -> bool:
    """Merge the owner-bound Advisor bridge into Muse's private settings.

    Muse's HTTP MCP transport cannot source a bearer token from an environment
    variable. The stdio bridge reads ``ADVISOR_TOKEN`` from the process or its
    owner-private token file and forwards it to HTTPS; the value is never
    written to settings.
    """
    if AGENT_KIND != "muse":
        return True
    settings_file = MUSE_CONFIG_HOME / "muse" / "settings.json"
    try:
        settings_file.parent.mkdir(parents=True, exist_ok=True)
        settings_file.parent.chmod(0o700)
        try:
            settings = json.loads(settings_file.read_text())
        except FileNotFoundError:
            settings = {"schema_version": 1}
        except Exception:
            logger.exception("Refusing to overwrite malformed Muse settings %s", settings_file)
            return False
        if not isinstance(settings, dict):
            logger.error("Refusing non-object Muse settings %s", settings_file)
            return False
        settings.setdefault("schema_version", 1)
        servers = settings.get("mcp_servers")
        if servers is None:
            servers = {}
            settings["mcp_servers"] = servers
        if not isinstance(servers, dict):
            logger.error("Muse mcp_servers must be an object in %s", settings_file)
            return False
        servers["advisor"] = {
            "transport": "stdio",
            "command": str(MUSE_MCP_PYTHON),
            "args": [
                str(MUSE_MCP_BRIDGE),
                "--url",
                MUSE_ADVISOR_URL,
                "--bearer-env",
                "ADVISOR_TOKEN",
                "--bearer-file",
                str(MUSE_ADVISOR_TOKEN_FILE),
            ],
            "env": {"PYTHONUNBUFFERED": "1"},
            "framing": "line_delimited_json",
        }
        servers["google"] = {
            "transport": "stdio",
            "command": str(MUSE_MCP_PYTHON),
            "args": [str(MUSE_GOOGLE_MCP_SCRIPT)],
            "env": {
                "GOOGLE_MCP_CREDENTIALS_DIR": str(MESSAGES_DIR / "connections" / "admin"),
                "GOOGLE_OAUTH_CLIENT_FILE": str(MESSAGES_DIR / "google_oauth_client.json"),
                "PYTHONUNBUFFERED": "1",
            },
            "framing": "line_delimited_json",
        }
        servers["playwright-browser"] = {
            "transport": "stdio",
            "command": str(MUSE_MCP_PYTHON),
            "args": [str(MUSE_BROWSER_MCP_PROXY)],
            "env": {
                "PYTHONUNBUFFERED": "1",
                "TMUX_DASH_BROWSER_CDP_PORT": "9222",
                "TMUX_DASH_BROWSER_ID": "default",
                "TMUX_DASH_BROWSER_OUTPUT_DIR": str(
                    Path.home() / ".playwright-mcp" / "default"
                ),
                "TMUX_DASH_CONTROLLER_SOCKET": str(CONTROLLER_SOCKET),
                "TMUX_DASH_HOST_HOME": str(Path.home()),
            },
            "framing": "line_delimited_json",
        }
        rendered = json.dumps(settings, indent=2, sort_keys=True) + "\n"
        current = settings_file.read_text() if settings_file.exists() else ""
        if rendered != current:
            tmp = settings_file.with_name(settings_file.name + ".tmp")
            tmp.write_text(rendered)
            tmp.chmod(0o600)
            os.replace(tmp, settings_file)
        settings_file.chmod(0o600)
        return True
    except Exception:
        logger.exception("Could not configure Muse runtime settings")
        return False


async def _refresh_model_catalog(force: bool = False) -> bool:
    global MODEL_CATALOG, ALLOWED_SESSION_MODELS
    if AGENT_KIND == "muse":
        return False
    try:
        last_check = 0.0
        try:
            last_check = float(json.loads(MODELS_FILE.read_text()).get("last_check", 0))
        except Exception:
            pass
        now = time.time()
        if not force and now - last_check < MODEL_CHECK_INTERVAL:
            return False
        detected = await asyncio.to_thread(_fetch_codex_model_catalog)
        if not detected:
            return False
        seen = set()
        merged = []
        for row in detected + _SEED_MODEL_CATALOG:
            if row[0] not in seen:
                seen.add(row[0])
                merged.append(list(row))
        changed = merged != MODEL_CATALOG
        MODEL_CATALOG = merged
        ALLOWED_SESSION_MODELS = [row[0] for row in MODEL_CATALOG]
        _save_model_catalog(MODEL_CATALOG, now)
        return changed
    except Exception:
        logger.debug("Codex model catalog refresh failed", exc_info=True)
        return False


async def _model_refresh_loop():
    await asyncio.sleep(20)
    while True:
        try:
            await _refresh_model_catalog()
        except Exception:
            logger.debug("Codex model refresh loop failed", exc_info=True)
        await asyncio.sleep(3600)


_CODEX_MCP_HEADER_RE = re.compile(r"^\s*\[\s*mcp_servers\s*\.\s*([^\].]+?)\s*[\].]")
_codex_mcp_decl_cache: dict[str, tuple[float, int, frozenset[str]]] = {}


def _codex_home_mcp_servers(codex_home: Path | None) -> frozenset[str]:
    """Names of the MCP servers a CODEX_HOME's ``config.toml`` really declares.

    Cached on (mtime, size) so starting a session does not re-read the file.
    """
    path = Path(codex_home or CODEX_HOME) / "config.toml"
    key = str(path)
    try:
        stat = path.stat()
    except OSError:
        _codex_mcp_decl_cache.pop(key, None)
        return frozenset()
    cached = _codex_mcp_decl_cache.get(key)
    if cached and cached[0] == stat.st_mtime and cached[1] == stat.st_size:
        return cached[2]
    names: set[str] = set()
    try:
        for line in path.read_text(errors="replace").splitlines():
            match = _CODEX_MCP_HEADER_RE.match(line)
            if match:
                names.add(match.group(1).strip().strip("\"'"))
    except OSError:
        return frozenset()
    resolved = frozenset(names)
    _codex_mcp_decl_cache[key] = (stat.st_mtime, stat.st_size, resolved)
    return resolved


# Codex validates every `mcp_servers.*` table while loading config.toml —
# including a table that only an `-c` override brought into existence. Sending
# `-c mcp_servers.openaiDeveloperDocs.enabled=false` to a CODEX_HOME whose
# config.toml does not declare that server therefore CREATES a server with no
# `command` and no `url`, and Codex refuses to start:
#
#     Error: failed to load configuration
#     Caused by: invalid transport in `mcp_servers.openaiDeveloperDocs`
#
# It exits before the TUI draws, the pane falls back to its parent login shell,
# and the account looks logged out. Member homes never declare that server, so
# every member session died this way while admin sessions (whose config.toml
# does declare it) were fine. Only send the override where the server exists.
_CODEX_DOCS_MCP_SERVER = "openaiDeveloperDocs"
_CODEX_DOCS_MCP_OVERRIDE = f"mcp_servers.{_CODEX_DOCS_MCP_SERVER}.enabled=false"
_CODEX_DOCS_OVERRIDE_RE = re.compile(
    r"\s+-c\s+(['\"]?)" + re.escape(_CODEX_DOCS_MCP_OVERRIDE) + r"\1"
)


def _launch_codex_cmd(
    cmd: str,
    pin_model: bool = True,
    resume: bool = False,
    codex_home: Path | None = None,
) -> str:
    """Build a Codex launch command using the account's standard configuration."""
    out = cmd.strip() or NEW_SESSION_CMD
    if resume:
        out = "codex resume --last"
        if "--yolo" in cmd or "--dangerously-bypass-approvals-and-sandbox" in cmd:
            out += " --yolo"
        elif "--sandbox" in cmd or " -s " in f" {cmd} ":
            out += " --sandbox workspace-write --ask-for-approval never"
    if pin_model and DEFAULT_MODEL and "--model" not in out and " -m " not in f" {out} ":
        out += " --model " + shlex.quote(DEFAULT_MODEL)
    # Strip any inherited copy first: a stored session command must not be able
    # to smuggle the override into a home that does not declare the server.
    out = _CODEX_DOCS_OVERRIDE_RE.sub("", out).strip()
    if (
        _DISABLE_STALLED_OPENAI_DOCS_MCP
        and _CODEX_DOCS_MCP_SERVER in _codex_home_mcp_servers(codex_home)
    ):
        out += " -c " + shlex.quote(_CODEX_DOCS_MCP_OVERRIDE)
    if not CODEX_API_FALLBACK_ENABLED:
        out = "env -u OPENAI_API_KEY " + out
    return out


def _muse_launch_prefix() -> str:
    """Environment that keeps Muse credentials and session data deployment-local."""
    return " ".join(
        (
            "env",
            "MUSE_NO_AUTO_UPDATE=1",
            "XDG_CONFIG_HOME=" + shlex.quote(str(MUSE_CONFIG_HOME)),
            "XDG_DATA_HOME=" + shlex.quote(str(MUSE_DATA_HOME)),
        )
    )


def _launch_agent_cmd(
    cmd: str,
    pin_model: bool = True,
    resume: bool = False,
    codex_home: Path | None = None,
) -> str:
    """Build the configured coding-agent command without changing Codex defaults."""
    if AGENT_KIND != "muse":
        return _launch_codex_cmd(
            cmd,
            pin_model=pin_model,
            resume=resume,
            codex_home=codex_home,
        )
    if resume:
        out = f"{shlex.quote(str(MUSE_BINARY))} --yolo resume --last"
    else:
        out = cmd.strip() or f"{shlex.quote(str(MUSE_BINARY))} --yolo"
    return _muse_launch_prefix() + " " + out


def _is_agent_process_command(command: str) -> bool:
    """Recognize the process name used by the selected coding-agent binary."""
    name = Path(str(command or "").strip().lower()).name
    if AGENT_KIND == "muse":
        return name == "muse" or name.startswith("muse-bin")
    return name == "codex"


def _session_launch_base(session_name: str = "", user: dict | None = None) -> str:
    """Use the canonical full-access launch for members and configured admin command."""
    if AGENT_KIND == "muse":
        return NEW_SESSION_CMD
    try:
        owner = user or (_user_for_session(session_name) if session_name else None)
        if owner and not _is_admin(owner):
            return "codex --yolo"
    except Exception:
        pass
    return NEW_SESSION_CMD


def _session_launch_identity_prefix(session_name: str) -> str:
    """Rebind account identity inside the login shell used by systemd-run.

    The shared OS login exports the admin Advisor token. A member's parent tmux
    shell may be correct, but ``bash -lc`` sources login files again, so the
    final child command must override both values after that startup sequence.
    """
    owner = _user_for_session(session_name)
    if owner and not _is_admin(owner):
        codex_home = _user_codex_config_dir(owner)
        token_path = codex_home / "advisor-token"
        return (
            "env CODEX_HOME="
            + shlex.quote(str(codex_home))
            + " ADVISOR_TOKEN=\"$(cat "
            + shlex.quote(str(token_path))
            + " 2>/dev/null)\""
        )
    token_path = Path.home() / ".advisor-token"
    return (
        "env -u CODEX_HOME ADVISOR_TOKEN=\"$(cat "
        + shlex.quote(str(token_path))
        + " 2>/dev/null)\""
    )



# --- Per-account UNIX users ------------------------------------------------
# Every member session used to run as nimrod_rotem, which made account
# isolation a prompt instruction rather than a kernel boundary: one `cat` read
# another account's advisor token and with it that account's advisor
# permissions. provision_accounts.py creates one UNIX user per account and
# writes the mapping here.
_ACCOUNT_UNIX_USABLE: dict[str, bool] = {}


def _account_unix_map_file() -> Path:
    """Resolved on demand: MESSAGES_DIR is defined further down this module."""
    return MESSAGES_DIR / "account-unix-users.json"


def _unix_account_usable(name: str) -> bool:
    """True when the account exists and nimrod_rotem may drop into it."""
    if not name:
        return False
    if name in _ACCOUNT_UNIX_USABLE:
        return _ACCOUNT_UNIX_USABLE[name]
    ok = False
    try:
        pwd.getpwnam(name)
        ok = subprocess.run(
            ["sudo", "-n", "-u", name, "true"],
            capture_output=True, timeout=10,
        ).returncode == 0
    except Exception:
        ok = False
    if not ok:
        logger.warning("unix account %s not usable; session stays on the shared login", name)
    _ACCOUNT_UNIX_USABLE[name] = ok
    return ok


def _account_unix_user(user: dict | None) -> str:
    """The UNIX account this member's session runs as, or "" for the old path."""
    if not user or _is_admin(user):
        return ""
    if os.environ.get("TMUX_DASH_PER_USER_UNIX", "1") == "0":
        return ""
    try:
        mapping = json.loads(_account_unix_map_file().read_text())
    except Exception:
        return ""
    name = str(mapping.get(str(user.get("id")), "") or "")
    return name if _unix_account_usable(name) else ""


def _session_unix_account_prefix(session_name: str, launch: str) -> str:
    """Drop the launch into the session owner's own UNIX user."""
    try:
        owner = _user_for_session(session_name)
    except Exception:
        return launch
    account = _account_unix_user(owner)
    if not account:
        return launch
    # bash -lc keeps the existing single-string command intact, and the advisor
    # token is read inside the account so the shared login never sees it.
    # The cd belongs here too: the account can enter its own project directory,
    # the shared parent shell cannot and must not.
    try:
        project_dir = _member_session_project_dir(owner, session_name)
        project_dir.mkdir(parents=True, exist_ok=True)
        launch = "cd -- " + shlex.quote(str(project_dir)) + " && " + launch
    except Exception:
        logger.debug("No project dir for %s; launching in place", session_name, exc_info=True)
    # The browser MCP proxy reaches the controller socket, the browser profiles
    # and the shared playwright CLI through the dashboard owner's home, which is
    # no longer $HOME now that the session runs as its own account.
    launch = "TMUX_DASH_HOST_HOME=" + shlex.quote(str(Path.home())) + " " + launch
    return (
        "sudo -n -u "
        + shlex.quote(account)
        + " -H bash -lc "
        + shlex.quote(launch)
    )


def _session_launch_command(
    session_name: str,
    base: str,
    *,
    pin_model: bool = True,
    resume: bool = False,
) -> str:
    """Build the configured agent command and keep its process tree scoped."""
    launch = _launch_agent_cmd(
        base,
        pin_model=pin_model,
        resume=resume,
        codex_home=_session_config_base(session_name),
    )
    launch = _session_launch_identity_prefix(session_name) + " " + launch
    launch = _session_unix_account_prefix(session_name, launch)
    return scoped_codex_command(
        session_name,
        launch,
        unit_prefix=AGENT_KIND,
        memory_high_mb=int(os.environ.get("TMUX_DASH_CODEX_MEMORY_HIGH_MB", "2048")),
        memory_max_mb=int(os.environ.get("TMUX_DASH_CODEX_MEMORY_MAX_MB", "4096")),
        tasks_max=int(os.environ.get("TMUX_DASH_CODEX_TASKS_MAX", "768")),
        cpu_weight=int(os.environ.get("TMUX_DASH_CODEX_CPU_WEIGHT", "100")),
    )


def _launch_agent_pane(
    session_name: str,
    project_dir: str | Path,
    launch_command: str,
    environment: dict[str, str],
) -> bool:
    """Replace a bootstrap pane with the agent without typing shell commands.

    ``tmux send-keys`` makes exports and the full launch command part of the
    terminal's visible screen and scrollback. ``respawn-pane`` supplies the
    command, cwd, and environment out-of-band, so the first terminal frame is
    the agent itself.
    """
    argv = [
        "tmux",
        "respawn-pane",
        "-k",
        "-t",
        session_name,
        "-c",
        str(project_dir),
    ]
    for key, value in sorted(environment.items()):
        if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", str(key)):
            logger.error("Refusing invalid pane environment name %r", key)
            return False
        if "\x00" in str(value):
            logger.error("Refusing NUL in pane environment value for %s", key)
            return False
        argv.extend(("-e", f"{key}={value}"))
    argv.append(launch_command)
    try:
        result = subprocess.run(
            argv,
            capture_output=True,
            text=True,
            timeout=15,
        )
    except Exception:
        logger.exception("Could not launch %s in tmux session '%s'", AGENT_DISPLAY_NAME, session_name)
        return False
    if result.returncode != 0:
        logger.error(
            "Could not launch %s in tmux session '%s': %s",
            AGENT_DISPLAY_NAME,
            session_name,
            (result.stderr or "unknown tmux error").strip(),
        )
        return False
    return True


_MUSE_PROJECT_CONTEXT_BEGIN = "<!-- BEGIN MUSE DASHBOARD RUNTIME (managed) -->"
_MUSE_PROJECT_CONTEXT_END = "<!-- END MUSE DASHBOARD RUNTIME (managed) -->"


def _prepare_muse_project_context(project_dir: str | Path) -> bool:
    """Make Muse's real runtime/context contract load in the session workspace."""
    if AGENT_KIND != "muse":
        return True
    root = Path(project_dir)
    target = root / "AGENTS.md"
    try:
        root.mkdir(parents=True, exist_ok=True)
        if target.is_symlink():
            logger.error("Refusing symlinked Muse project context %s", target)
            return False
        existing = target.read_text() if target.exists() else ""
        try:
            account_policy = _read_global_context().strip()
        except Exception:
            account_policy = "# MUSE account policy\n\nFollow the dashboard-managed account policy."
        managed = (
            f"{_MUSE_PROJECT_CONTEXT_BEGIN}\n"
            "# Muse dashboard runtime\n\n"
            f"- Muse is installed at `{MUSE_BINARY}`. This session uses "
            f"`MUSE_CONFIG_HOME={MUSE_CONFIG_HOME}` and `MUSE_DATA_HOME={MUSE_DATA_HOME}`; "
            "do not treat `CODEX_HOME` as Muse state.\n"
            "- Use Muse's native `read_memory`, `add_memory`, and `edit_memory` tools for "
            "durable Muse memory. Muse session logs live only under MUSE_DATA_HOME.\n"
            "- Built-in Muse skills and the account skills under `~/.agents/skills` are loaded "
            "at session open; read a skill with `read_skill` when its description applies.\n"
            "- The `advisor` MCP is connected with this account's owner-bound `ADVISOR_TOKEN`. "
            "Use its tools directly; never copy the token into a file or output.\n\n"
            f"{account_policy}\n"
            f"{_MUSE_PROJECT_CONTEXT_END}"
        )
        pattern = re.compile(
            re.escape(_MUSE_PROJECT_CONTEXT_BEGIN)
            + r".*?"
            + re.escape(_MUSE_PROJECT_CONTEXT_END),
            re.S,
        )
        if pattern.search(existing):
            updated = pattern.sub(managed, existing)
        else:
            updated = existing.rstrip() + ("\n\n" if existing.strip() else "") + managed + "\n"
        if updated != existing:
            target.write_text(updated)
        return True
    except Exception:
        logger.exception("Could not prepare Muse project context in %s", root)
        return False


# Compatibility aliases used by newer Grabo paths while the implementation is Codex.
def _launch_claude_cmd(
    cmd: str, pin_model: bool = True, codex_home: Path | None = None
) -> str:
    return _launch_codex_cmd(cmd, pin_model=pin_model, codex_home=codex_home)


def _restore_default_model_setting():
    """Keep the default Codex config aligned with the dashboard selection."""
    if AGENT_KIND == "muse":
        return
    try:
        CODEX_HOME.mkdir(parents=True, exist_ok=True)
        cfg = CODEX_HOME / "config.toml"
        existing = cfg.read_text() if cfg.exists() else ""
        managed = {
            "model": DEFAULT_MODEL,
            "model_reasoning_effort": _CODEX_DEFAULT_REASONING_EFFORT,
            "sandbox_mode": "danger-full-access",
            "approval_policy": "never",
        }
        merged = _merge_top_level_toml_keys(existing, managed)
        merged = _ensure_codex_project_trust(merged, os.getcwd())
        if merged != existing:
            _backup_before_dashboard_write(cfg)
            cfg.write_text(merged)
    except Exception:
        logger.debug("Failed to align default Codex config", exc_info=True)


def _model_flag_for_relaunch(session_name: str) -> str:
    try:
        model = _get_session_model(session_name) or DEFAULT_MODEL
    except Exception:
        model = DEFAULT_MODEL
    return f" --model {shlex.quote(model)}" if model else ""

